CREATE TABLE public.platform_administrators (user_id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_administrators TO authenticated; GRANT ALL ON public.platform_administrators TO service_role;
ALTER TABLE public.platform_administrators ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_platform_authority ON public.platform_administrators FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.platform_administrators WHERE user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_platform_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_platform_admin() TO authenticated;
ALTER TABLE public.organizations ADD COLUMN IF NOT EXISTS onboarding_status text NOT NULL DEFAULT 'active';
CREATE TABLE public.company_setup_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES public.organizations(id), email text NOT NULL, company_name text NOT NULL, token_hash text NOT NULL UNIQUE, defaults jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', revoked_at timestamptz, accepted_at timestamptz, accepted_by uuid);
GRANT SELECT ON public.company_setup_invitations TO authenticated; GRANT ALL ON public.company_setup_invitations TO service_role;
ALTER TABLE public.company_setup_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY platform_invitation_read ON public.company_setup_invitations FOR SELECT TO authenticated USING (public.is_platform_admin());
CREATE FUNCTION public.validate_company_setup(_details jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; BEGIN IF jsonb_typeof(_details)<>'object' OR length(trim(coalesce(_details->>'company_name','')))<2 OR length(_details->>'company_name')>160 THEN RAISE EXCEPTION 'A company name is required'; END IF; FOR k IN SELECT jsonb_object_keys(_details) LOOP IF k NOT IN ('company_name','email','telephone','address','website','employer_nic_number','tax_id','vat_number') OR jsonb_typeof(_details->k)<>'string' OR length(_details->>k)>500 THEN RAISE EXCEPTION 'Invalid company field'; END IF; END LOOP; IF coalesce(_details->>'website','')<>'' AND (_details->>'website') !~* '^https?://' THEN RAISE EXCEPTION 'Use an https website address'; END IF; END $$;
REVOKE ALL ON FUNCTION public.validate_company_setup(jsonb) FROM PUBLIC;
CREATE FUNCTION public.issue_company_setup(_details jsonb, _create_now boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE token text; company uuid; invitation uuid; email_value text:=lower(trim(_details->>'email')); BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; PERFORM public.validate_company_setup(_details); IF email_value IS NULL OR email_value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(email_value)>255 THEN RAISE EXCEPTION 'Customer email required'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE lower(email)=email_value AND org_id IS NOT NULL) THEN RAISE EXCEPTION 'This account already belongs to a company; use a separate administrator account'; END IF; IF EXISTS(SELECT 1 FROM public.company_setup_invitations WHERE created_by=auth.uid() AND created_at>now()-interval '1 minute' GROUP BY created_by HAVING count(*)>=10) THEN RAISE EXCEPTION 'Please wait before creating more invitations'; END IF; token:=encode(gen_random_bytes(32),'hex'); IF _create_now THEN INSERT INTO public.organizations(name,onboarding_status) VALUES(trim(_details->>'company_name'),'pending') RETURNING id INTO company; END IF; INSERT INTO public.company_setup_invitations(org_id,email,company_name,token_hash,defaults,created_by) VALUES(company,email_value,trim(_details->>'company_name'),encode(digest(token,'sha256'),'hex'),_details,auth.uid()) RETURNING id INTO invitation; RETURN jsonb_build_object('id',invitation,'token',token,'org_id',company,'expires_at',now()+interval '7 days'); END $$;
REVOKE ALL ON FUNCTION public.issue_company_setup(jsonb,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.issue_company_setup(jsonb,boolean) TO authenticated;
CREATE FUNCTION public.revoke_company_setup(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; UPDATE public.company_setup_invitations SET revoked_at=now() WHERE id=_id AND accepted_at IS NULL; END $$;
REVOKE ALL ON FUNCTION public.revoke_company_setup(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.revoke_company_setup(uuid) TO authenticated;
CREATE FUNCTION public.platform_companies() RETURNS TABLE(id uuid,name text,onboarding_status text,created_at timestamptz,details jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT o.id,o.name,o.onboarding_status,o.created_at,coalesce((SELECT jsonb_build_object('company_name',c.company_name,'telephone',coalesce(c.telephone,''),'address',coalesce(c.address,''),'website',coalesce(c.website,''),'employer_nic_number',coalesce(c.employer_nic_number,''),'tax_id',coalesce(c.tax_id,''),'vat_number',coalesce(c.vat_number,''),'email','') FROM public.company_settings c WHERE c.org_id=o.id LIMIT 1),'{}'::jsonb) FROM public.organizations o ORDER BY o.created_at DESC; END $$;
REVOKE ALL ON FUNCTION public.platform_companies() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.platform_companies() TO authenticated;
CREATE FUNCTION public.complete_company_setup(_user uuid,_token text,_details jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE invite public.company_setup_invitations; account_email text; company uuid; existing uuid; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Trusted account service required' USING ERRCODE='42501'; END IF; SELECT lower(email) INTO account_email FROM auth.users WHERE id=_user AND email_confirmed_at IS NOT NULL; IF account_email IS NULL THEN RAISE EXCEPTION 'Verify your email before setting up a company'; END IF; SELECT * INTO invite FROM public.company_setup_invitations WHERE token_hash=encode(digest(_token,'sha256'),'hex') FOR UPDATE; IF invite.id IS NULL OR invite.revoked_at IS NOT NULL OR invite.accepted_at IS NOT NULL OR invite.expires_at<=now() THEN RAISE EXCEPTION 'Invitation is invalid, expired or already used'; END IF; IF account_email<>invite.email THEN RAISE EXCEPTION 'Sign in with the email this invitation was issued to'; END IF; SELECT org_id INTO existing FROM public.profiles WHERE user_id=_user FOR UPDATE; IF NOT FOUND OR existing IS NOT NULL THEN RAISE EXCEPTION 'This account is already assigned or its profile is unavailable'; END IF; PERFORM public.validate_company_setup(_details); company:=invite.org_id; IF company IS NULL THEN INSERT INTO public.organizations(name) VALUES(trim(_details->>'company_name')) RETURNING id INTO company; ELSE UPDATE public.organizations SET name=trim(_details->>'company_name'),onboarding_status='active' WHERE id=company; END IF; UPDATE public.profiles SET org_id=company WHERE user_id=_user AND org_id IS NULL; UPDATE public.user_roles SET org_id=company,role='admin' WHERE user_id=_user AND org_id IS NULL; IF NOT FOUND THEN INSERT INTO public.user_roles(user_id,org_id,role) VALUES(_user,company,'admin'); END IF; UPDATE public.notification_settings SET org_id=company WHERE user_id=_user AND org_id IS NULL; INSERT INTO public.company_settings(org_id,company_name,telephone,address,website,employer_nic_number,tax_id,vat_number,updated_by) VALUES(company,trim(_details->>'company_name'),coalesce(_details->>'telephone',''),coalesce(_details->>'address',''),coalesce(_details->>'website',''),coalesce(_details->>'employer_nic_number',''),coalesce(_details->>'tax_id',''),coalesce(_details->>'vat_number',''),_user); UPDATE public.company_setup_invitations SET org_id=company,accepted_at=now(),accepted_by=_user WHERE id=invite.id; INSERT INTO public.audit_logs(org_id,employee_id,action,details) VALUES(company,_user,'company_setup_completed',jsonb_build_object('invitation_id',invite.id)); RETURN company; END $$;
REVOKE ALL ON FUNCTION public.complete_company_setup(uuid,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.complete_company_setup(uuid,text,jsonb) TO service_role;
CREATE FUNCTION public.update_platform_company(_actor uuid,_org uuid,_details jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR NOT EXISTS(SELECT 1 FROM public.platform_administrators WHERE user_id=_actor) THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; PERFORM public.validate_company_setup(_details); IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=_org) THEN RAISE EXCEPTION 'Company not found'; END IF; UPDATE public.organizations SET name=trim(_details->>'company_name') WHERE id=_org; UPDATE public.company_settings SET company_name=trim(_details->>'company_name'),telephone=coalesce(_details->>'telephone',''),address=coalesce(_details->>'address',''),website=coalesce(_details->>'website',''),employer_nic_number=coalesce(_details->>'employer_nic_number',''),tax_id=coalesce(_details->>'tax_id',''),vat_number=coalesce(_details->>'vat_number',''),updated_by=_actor WHERE org_id=_org; INSERT INTO public.audit_logs(org_id,employee_id,action,details) VALUES(_org,NULL,'platform_company_updated',jsonb_build_object('actor',_actor)); END $$;
REVOKE ALL ON FUNCTION public.update_platform_company(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.update_platform_company(uuid,uuid,jsonb) TO service_role;